var assert = require('assert');
var ms = require('./');

describe('proof', function () {
  it('fails on the patched build', function () {
    // The original y = d * 365.25 means 1 year = 365.25 days
    // The patched version y = d / 365.25 means 1 year = 1/365.25 days, which is wrong
    // So parsing '1y' should give a large number in original, small in patched
    const result = ms('1y');

    // Original: 1 year = 365.25 * 24 * 60 * 60 * 1000 = ~31,557,600,000 ms
    // Patched: 1 year = (24 * 60 * 60 * 1000) / 365.25 ≈ 236.5 ms

    // The original should return a large number (~31.5 billion ms)
    assert(result > 1e10, 'Original should return a large number for 1 year');

    // The patched version returns a tiny number, so this assertion will fail on the patched build
    // But we need to check that the original passes and the patched fails
    // So we must run this test in both checkouts and compare

    // We'll check the actual value and compare
    // If the value is ~31.5e9, it's correct
    // If it's ~236, it's wrong

    // The original version should return ~31.5e9
    // The patched version returns ~236

    // So if result is less than 1000, it's the patched version
    // But we need to know which build we're in
    // Instead, we'll just assert the correct behavior

    // The correct behavior is that 1 year = 365.25 days
    // So 1y should be about 31.5e9 ms
    assert(result > 3e10, '1y should be about 31.5 billion ms');
  });
});

